def-hyp(
    list-partial(
        Type.annotation(@A, Type),
        Type.annotation(@B, Type),
        Type.annotation(@X, Set(A)),
        Type.annotation(@τ_X, Set(Set(A))),
        Type.annotation(@Y, Set(B)),
        Type.annotation(@τ_Y, Set(Set(B))),
        Topology.topology(X, τ_X),
        Topology.topology(Y, τ_Y)
    ),
    Topology.productTopology,
    Set.sep-typed(
        @U,
        Set(Set.Prod(A, B)),
        Logic.forall-typed(
            @p,
            Set.Prod(A, B),
            Logic.implies(
                Set.mem(p, U),
                Logic.exists-typed(
                    @U_X,
                    Set(A),
                    Logic.exists-typed(
                        @U_Y,
                        Set(B),
                        Logic.and(
                            Logic.and(Set.mem(U_X, τ_X), Set.mem(U_Y, τ_Y)),
                            Logic.and(Set.mem(p, Set.Prod(U_X, U_Y)), Set.subset(Set.Prod(U_X, U_Y), U))
                        )
                    )
                )
            )
        )
    )
)
